import {
  CB_CONNECT_SANDBOX_DEFAULTS,
  type CbConnectEndpoints,
  type CbConnectEndpointsPublic,
} from "./endpoints-shared";

function envUrl(key: string): string {
  return (process.env[key] ?? "").trim();
}

/** Merge sandbox defaults with optional CBCON_URL_* overrides. */
export function resolveCbConnectEndpoints(): CbConnectEndpoints {
  const d = CB_CONNECT_SANDBOX_DEFAULTS;
  return {
    accountBalanceHealthUrl:
      envUrl("CBCON_URL_ACCOUNT_BALANCE_HEALTH") || d.accountBalanceHealthUrl,
    accountBalanceUrl:
      envUrl("CBCON_URL_ACCOUNT_BALANCE") || d.accountBalanceUrl,
    swiftG4cUrl: envUrl("CBCON_URL_SWIFT_G4C") || d.swiftG4cUrl,
    oauthTokenUrl: envUrl("CBCON_URL_OAUTH_TOKEN") || d.oauthTokenUrl,
    instantPaymentInitiationUrl:
      envUrl("CBCON_URL_INSTANT_PAYMENT_INIT") || d.instantPaymentInitiationUrl,
    instantPaymentStatusUrl:
      envUrl("CBCON_URL_INSTANT_PAYMENT_STATUS") || d.instantPaymentStatusUrl,
    instantPaymentHealthUrl:
      envUrl("CBCON_URL_INSTANT_PAYMENT_HEALTH") || d.instantPaymentHealthUrl,
    verificationOfPayeeUrl:
      envUrl("CBCON_URL_VOP") || d.verificationOfPayeeUrl,
    accountPreValidationUrl:
      envUrl("CBCON_URL_ACCOUNT_PREVALIDATION") || d.accountPreValidationUrl,
    fx4CashInitiationUrl:
      envUrl("CBCON_URL_FX4CASH_INIT") || d.fx4CashInitiationUrl,
    fx4CashStatusReportUrl:
      envUrl("CBCON_URL_FX4CASH_STATUS") || d.fx4CashStatusReportUrl,
    fx4CashValueDateUrl:
      envUrl("CBCON_URL_FX4CASH_VALUE_DATE") || d.fx4CashValueDateUrl,
    statementsRequestUrl:
      envUrl("CBCON_URL_STATEMENTS_REQUEST") || d.statementsRequestUrl,
    statementsLoadUrl:
      envUrl("CBCON_URL_STATEMENTS_LOAD") || d.statementsLoadUrl,
    statementsVersion: (envUrl("CBCON_STATEMENTS_VERSION") ||
      d.statementsVersion) as CbConnectEndpoints["statementsVersion"],
  };
}

/**
 * Compatibility shim for HealthFlow services that called the team endpoints store.
 * `teamId` is ignored — MCP uses process env + sandbox defaults.
 */
export async function cbConnectEndpointsGetPublic(
  _teamId?: string
): Promise<CbConnectEndpointsPublic> {
  const endpoints = resolveCbConnectEndpoints();
  return {
    ...endpoints,
    updatedAt: null,
    hasStoredEndpoints: false,
    source: "defaults",
  };
}

/**
 * Deutsche Bank CB-Connect — Bootstrap aus Server-Env (.env.local).
 * Nur serverseitig; Werte nie an den Client zurückgeben (außer nicht-sensitive IDs).
 */

export type CbconEnvCredentials = {
  clientId: string;
  keyId: string;
  clientSecret: string;
  xCustomerIdentifier: string;
  certificateBase64: string;
  certificatePassword: string;
};

function env(key: string): string {
  const direct = (process.env[key] ?? "").trim();
  if (direct) return direct;
  // .env mit Leerzeichen vor dem Key: " CBCON_CLIENTID=…"
  for (const [k, v] of Object.entries(process.env)) {
    if (k.trim() === key && typeof v === "string") return v.trim();
  }
  return "";
}

/** Liest CBCON_* inkl. bekannter Schreibvarianten (CERTTIFICATE, PASSWORT). */
export function readCbconEnv(): CbconEnvCredentials {
  return {
    clientId: env("CBCON_CLIENTID"),
    keyId: env("CBCON_KEYID"),
    clientSecret: env("CBCON_CLIENTSECRET"),
    xCustomerIdentifier: env("CBCON_XCUSTOMERIDENTIFIER"),
    certificateBase64:
      env("CBCON_CERTIFICATEBASE64") || env("CBCON_CERTTIFICATEBASE64"),
    certificatePassword:
      env("CBCON_CERTIFICATEPASSWORD") || env("CBCON_CERTIFICATEPASSWORT"),
  };
}

/** Nur Sandbox/Dev: TLS-Serverprüfung abschalten (Node kennt DB-CA nicht). */
export function readCbconTlsInsecure(): boolean {
  const v = env("CBCON_TLS_INSECURE").toLowerCase();
  return v === "1" || v === "true" || v === "yes";
}

export function hasCbconEnv(): boolean {
  const e = readCbconEnv();
  return Boolean(
    e.clientId ||
      e.keyId ||
      e.clientSecret ||
      e.xCustomerIdentifier ||
      e.certificateBase64 ||
      e.certificatePassword
  );
}

import forge from "node-forge";

/** Privater Schlüssel aus PKCS#12 (für CB-Connect HTTP-Signatur). */
export function getPrivateKeyFromP12(
  pfx: Buffer,
  passphrase: string
): forge.pki.PrivateKey {
  const der = forge.util.createBuffer(pfx.toString("binary"));
  const asn1 = forge.asn1.fromDer(der);
  const p12 = forge.pkcs12.pkcs12FromAsn1(asn1, passphrase);

  const shrouded = p12.getBags({ bagType: forge.pki.oids.pkcs8ShroudedKeyBag });
  const shroudedBag =
    shrouded[forge.pki.oids.pkcs8ShroudedKeyBag]?.[0]?.key;
  if (shroudedBag) return shroudedBag;

  const plain = p12.getBags({ bagType: forge.pki.oids.keyBag });
  const plainBag = plain[forge.pki.oids.keyBag]?.[0]?.key;
  if (plainBag) return plainBag;

  throw new Error(
    "Kein privater Schlüssel im PKCS#12 gefunden (Signatur nicht möglich)."
  );
}

import forge from "node-forge";

export type P12TlsMaterial = {
  /** PEM-Zertifikate aus dem P12 (inkl. CA-Kette) für Server-Trust. */
  caPems: string[];
};

/** CA-/Client-Zertifikate aus PKCS#12 für Node-TLS (mTLS + ggf. Issuer-Trust). */
export function extractCaPemsFromP12(
  pfx: Buffer,
  passphrase: string
): P12TlsMaterial {
  const der = forge.util.createBuffer(pfx.toString("binary"));
  const asn1 = forge.asn1.fromDer(der);
  const p12 = forge.pkcs12.pkcs12FromAsn1(asn1, passphrase);

  const caPems: string[] = [];
  const certBags = p12.getBags({ bagType: forge.pki.oids.certBag });
  for (const bag of certBags[forge.pki.oids.certBag] ?? []) {
    if (bag.cert) {
      caPems.push(forge.pki.certificateToPem(bag.cert));
    }
  }

  return { caPems };
}

import { readCbconEnv } from "./env-config";

export type NativeBankResolvedCredentials = {
  clientId: string;
  clientSecret: string;
  xCustomerIdentifier: string;
  keyId: string;
  certificateBase64: string;
  certificatePassword: string;
};

/**
 * CB-Connect credentials for the MCP process.
 * Loaded from CBCON_* env vars (no team store).
 * `teamId` is accepted for API compatibility with HealthFlow services and ignored.
 */
export async function nativeBankGetResolvedCredentials(
  _teamId?: string
): Promise<NativeBankResolvedCredentials> {
  const e = readCbconEnv();
  return {
    clientId: e.clientId,
    clientSecret: e.clientSecret,
    xCustomerIdentifier: e.xCustomerIdentifier,
    keyId: e.keyId,
    certificateBase64: e.certificateBase64,
    certificatePassword: e.certificatePassword,
  };
}

export function validateCredentialsForToken(
  creds: NativeBankResolvedCredentials
): string | null {
  if (!creds.clientId) return "Client ID fehlt.";
  if (!creds.clientSecret) return "Client Secret fehlt.";
  return null;
}

export function validateCredentialsForSignedApi(
  creds: NativeBankResolvedCredentials
): string | null {
  const tokenErr = validateCredentialsForToken(creds);
  if (tokenErr) return tokenErr;
  if (!creds.certificateBase64) return "mTLS-Zertifikat fehlt.";
  if (!creds.certificatePassword) return "Zertifikats-Passwort fehlt.";
  return null;
}

export function validateCredentialsForBankingApi(
  creds: NativeBankResolvedCredentials
): string | null {
  const signedErr = validateCredentialsForSignedApi(creds);
  if (signedErr) return signedErr;
  if (!creds.xCustomerIdentifier) return "X-Customer-Identifier fehlt.";
  return null;
}

export function validateCredentialsForApi(
  creds: NativeBankResolvedCredentials
): string | null {
  return validateCredentialsForSignedApi(creds);
}

import type {
  FinapiAccountSummary,
  FinapiBankConnectionSummary,
} from "./shared";

function asRecord(v: unknown): Record<string, unknown> | null {
  return v && typeof v === "object" ? (v as Record<string, unknown>) : null;
}

export function parseFinapiBankConnections(
  raw: unknown
): FinapiBankConnectionSummary[] {
  const root = asRecord(raw);
  const list = Array.isArray(root?.connections)
    ? root!.connections
    : Array.isArray(root?.bankConnections)
      ? root!.bankConnections
      : Array.isArray(raw)
        ? raw
        : [];

  const now = Date.now();
  return list
    .map((item): FinapiBankConnectionSummary | null => {
      const o = asRecord(item);
      if (!o || typeof o.id !== "number") return null;
      const bank = asRecord(o.bank);
      return {
        id: o.id,
        name: typeof o.name === "string" ? o.name : `Verbindung ${o.id}`,
        bankName:
          typeof bank?.name === "string"
            ? bank.name
            : typeof o.bankName === "string"
              ? o.bankName
              : null,
        updatedAt: now,
      };
    })
    .filter((x): x is FinapiBankConnectionSummary => x !== null);
}

export function parseFinapiAccounts(raw: unknown): FinapiAccountSummary[] {
  const root = asRecord(raw);
  const list = Array.isArray(root?.accounts)
    ? root!.accounts
    : Array.isArray(raw)
      ? raw
      : [];

  const now = Date.now();
  return list
    .map((item): FinapiAccountSummary | null => {
      const o = asRecord(item);
      if (!o || typeof o.id !== "number") return null;
      const balance = asRecord(o.balance);
      return {
        id: o.id,
        name:
          typeof o.accountName === "string" ? o.accountName : `Konto ${o.id}`,
        iban: typeof o.iban === "string" ? o.iban : null,
        accountType: typeof o.accountType === "string" ? o.accountType : null,
        balance:
          typeof balance?.value === "number"
            ? balance.value
            : typeof o.balance === "number"
              ? o.balance
              : null,
        currency:
          typeof balance?.currency === "string"
            ? balance.currency
            : typeof o.currency === "string"
              ? o.currency
              : null,
        bankConnectionId:
          typeof o.bankConnectionId === "number" ? o.bankConnectionId : null,
        syncedAt: now,
      };
    })
    .filter((x): x is FinapiAccountSummary => x !== null);
}

import type {
