import {
  finapiEndpointsForEnvironment,
  type FinapiEnvironment,
  type FinapiEndpoints,
} from "./shared";

export type FinapiEnvCredentials = {
  clientId: string;
  clientSecret: string;
  environment: FinapiEnvironment;
  userId: string;
  userPassword: string;
  publicOrigin: string | null;
  endpoints: FinapiEndpoints;
};

function env(key: string): string {
  const direct = (process.env[key] ?? "").trim();
  if (direct) return direct;
  for (const [k, v] of Object.entries(process.env)) {
    if (k.trim() === key && typeof v === "string") return v.trim();
  }
  return "";
}

export function readFinapiEnvironment(): FinapiEnvironment {
  const raw = env("FINAPI_ENVIRONMENT").toLowerCase();
  return raw === "live" ? "live" : "sandbox";
}

/** Öffentliche HTTPS-Origin für finAPI-Callbacks (ngrok, Vercel, …). */
export function readFinapiPublicOrigin(): string | null {
  const candidates = [
    process.env.FINAPI_PUBLIC_ORIGIN,
    process.env.NEXT_PUBLIC_APP_URL,
    process.env.VERCEL_URL ? `https://${process.env.VERCEL_URL}` : "",
  ]
    .map((s) => (s ?? "").trim())
    .filter(Boolean);

  for (const raw of candidates) {
    try {
      const url = new URL(raw.startsWith("http") ? raw : `https://${raw}`);
      if (url.protocol === "https:") {
        return url.origin;
      }
    } catch {
      /* next */
    }
  }
  return null;
}

export function readFinapiEnv(): FinapiEnvCredentials {
  const environment = readFinapiEnvironment();
  return {
    clientId:
      env("FINAPI_CLIENT_ID") ||
      env("FINAPI_ACCESS_CLIENT_ID") ||
      env("FinapiClientId"),
    clientSecret:
      env("FINAPI_CLIENT_SECRET") ||
      env("FINAPI_ACCESS_CLIENT_SECRET") ||
      env("FinapiClientSecret"),
    environment,
    userId: env("FINAPI_USER_ID"),
    userPassword: env("FINAPI_USER_PASSWORD"),
    publicOrigin: readFinapiPublicOrigin(),
    endpoints: finapiEndpointsForEnvironment(environment),
  };
}

export function hasFinapiEnv(): boolean {
  const e = readFinapiEnv();
  return Boolean(e.clientId || e.clientSecret);
}

/** finAPI Web Form 2.0 — Endzustände (siehe finAPI-Doku / Zahlungslink-Flow). */
export const FINAPI_WEB_FORM_FINAL_STATUSES = new Set([
  "COMPLETED",
  "COMPLETED_WITH_ERROR",
  "ABORTED",
  "EXPIRED",
  "CANCELLED",
]);

export function isFinapiWebFormFinalStatus(status: string): boolean {
  return FINAPI_WEB_FORM_FINAL_STATUSES.has(status.trim().toUpperCase());
}

/** Access-Payment-ID aus Web-Form-Antwort (payload.paymentId). */
export function finapiPaymentIdFromWebForm(
  webForm: Record<string, unknown>
): number | null {
  const payload = webForm.payload;
  if (!payload || typeof payload !== "object") return null;
  const pid = (payload as { paymentId?: unknown }).paymentId;
  return typeof pid === "number" && Number.isFinite(pid) ? pid : null;
}

/** Bankverbindungs-ID nach bankConnectionImport (payload.bankConnectionId). */
export function finapiBankConnectionIdFromWebForm(
  webForm: Record<string, unknown>
): number | null {
  const payload = webForm.payload;
  if (!payload || typeof payload !== "object") return null;
  const raw = (payload as { bankConnectionId?: unknown }).bankConnectionId;
  if (typeof raw === "number" && Number.isFinite(raw)) return raw;
  if (typeof raw === "string" && raw.trim()) {
    const n = Number(raw.trim());
    if (Number.isFinite(n)) return n;
  }
  return null;
}

export function parseStoredFinapiPaymentId(
  stored: string | undefined
): number | null {
  const raw = stored?.trim();
  if (!raw) return null;
  const n = Number(raw);
  return Number.isFinite(n) ? n : null;
}

import { readFinapiEnv, type FinapiEnvCredentials } from "./env-config";
